const CryptoJS = require('crypto-js');
const btoa = require('btoa');

//Utility Functions

function reverseString(str) {
    return str.split("").reverse().join("");
}

function generateNumericId() {
    return Math.floor(1000000 + Math.random() * 9000000).toString();
}

function getCurrentDateTime() {
    const now = new Date();
    return `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}${String(now.getHours()).padStart(2, '0')}${String(now.getMinutes()).padStart(2, '0')}${String(now.getSeconds()).padStart(2, '0')}`;
}

//Generate MAC using the provided key and requestBody
function generateMAC(key, argumentsJson) {

    const reversedJson = reverseString(argumentsJson);
    const reversedkey = reverseString(key);
    const combined = reversedJson + reversedkey;

    // Base64 encode properly using CryptoJS
    const base64Encoded = CryptoJS.enc.Base64.stringify(CryptoJS.enc.Utf8.parse(combined));
    const sha512Hash = CryptoJS.SHA512(base64Encoded).toString(CryptoJS.enc.Hex);

    const positions = [0, 8, 16, 24, 32, 40, 48, 56, 64, 72, 80, 88, 96, 104, 112, 120];
    let mac = "";
    positions.forEach(pos => mac += sha512Hash.charAt(pos));
    return mac.toUpperCase();
}

